3	namespace App\Jobs;
4	
5	use App\Models\Core\Site\SiteMedia;
6	use App\Services\Cache\SiteCacheService;
7	use App\Services\Media\ImageVariantService;
8	use App\Services\Media\UnprocessableImageException;
9	use Illuminate\Bus\Queueable;
10	use Illuminate\Contracts\Queue\ShouldQueue;
11	use Illuminate\Foundation\Bus\Dispatchable;
12	use Illuminate\Queue\InteractsWithQueue;
13	use Illuminate\Queue\SerializesModels;
14	use Illuminate\Support\Facades\Log;
15	use Illuminate\Support\Facades\Storage;
16	use Throwable;
17	
18	/**
19	 * Generates all WebP variants for a freshly uploaded image.
20	 *
21	 * State transitions:
22	 *   pending → processing (job starts)
23	 *   processing → ready   (all variants created)
24	 *   processing → failed  (unrecoverable error after all retries)
25	 */
26	// V2: Generates WebP variants for uploaded images. Updates SiteMedia state (pending → ready/failed). Queue: images.
27	class ProcessImageVariantsJob implements ShouldQueue
28	{
29	    use Dispatchable, InteractsWithQueue, Queueable, SerializesModels;
30	
31	    public int $tries = 3;
32	
33	    public int $backoff = 30;
34	
35	    /**
36	     * @param  string  $originalPath  Path of the original on the media disk.
37	     * @param  string  $imageId  UUID of the SiteMedia row.
38	     * @param  string  $basePath  Directory prefix for variant storage.
39	     */
40	    public function __construct(
41	        public readonly string $originalPath,
42	        public readonly string $imageId,
43	        public readonly string $basePath,
44	    ) {
45	        $this->onQueue('images');
46	    }
47	
48	    public function handle(ImageVariantService $service): void
49	    {
50	        Log::info('ProcessImageVariantsJob: starting', [
51	            'image_id' => $this->imageId,
52	            'original_path' => $this->originalPath,
53	        ]);
54	
55	        $siteMedia = SiteMedia::withTrashed()->find($this->imageId);
56	
57	        if (! $siteMedia) {
58	            Log::warning('ProcessImageVariantsJob: SiteMedia row no longer exists, skipping.', [
59	                'image_id' => $this->imageId,
60	            ]);
61	
62	            return;
63	        }
64	
65	        if ($siteMedia->trashed()) {
66	            Log::info('ProcessImageVariantsJob: SiteMedia row is soft-deleted, skipping.', [
67	                'image_id' => $this->imageId,
68	            ]);
69	
70	            return;
71	        }
72	
73	        SiteMedia::query()
74	            ->where('id', $this->imageId)
75	            ->whereNull('deleted_at')
76	            ->update([
77	                'processing_state' => SiteMedia::PROCESSING_STATE_PROCESSING,
78	                'processing_error' => null,
79	            ]);
80	
81	        $diskName = $service->resolvedDiskName();
82	        $disk = Storage::disk($diskName);
83	
84	        if (! $disk->exists($this->originalPath)) {
85	            $this->markFailed('Original file not found on media disk.');
86	            $this->fail(new \RuntimeException('Original file not found on media disk.'));
87	
88	            return;
89	        }
90	
91	        $localTmp = null;
92	
93	        try {
94	            $localTmp = tempnam(sys_get_temp_dir(), 'sidest_orig_');
95	            if (! $localTmp) {
96	                throw new \RuntimeException('Failed to create temporary file.');
97	            }
98	
99	            $content = $disk->get($this->originalPath);
100	            if (! file_put_contents($localTmp, $content)) {
101	                throw new \RuntimeException('Failed to write original to temp file.');
102	            }
103	
104	            $service->processVariants(
105	                originalTmpPath: $localTmp,
106	                imageId: $this->imageId,
107	                basePath: $this->basePath,
108	            );
109	
110	            SiteMedia::query()
111	                ->where('id', $this->imageId)
112	                ->whereNull('deleted_at')
113	                ->update([
114	                    'processing_state' => SiteMedia::PROCESSING_STATE_READY,
115	                    'processing_error' => null,
116	                ]);
117	
118	            // If this was a brand design asset, bust the Hydrogen brand-design
119	            // cache so the compressed variants replace the pre-processing URL
120	            // (listDesignMedia filters on processing_state=ready, so the
121	            // payload changes the moment this row flips to ready).
122	            if ($siteMedia->pool === SiteMedia::POOL_DESIGN && $siteMedia->site_id) {
123	                app(SiteCacheService::class)->forgetBrandDesign((string) $siteMedia->site_id);
124	            }
125	
126	            Log::info('ProcessImageVariantsJob: completed.', ['image_id' => $this->imageId]);
127	        } catch (UnprocessableImageException $e) {
128	            // Permanent validation failure (e.g. pixel-count guard rejection).
129	            // Retrying cannot succeed, so mark failed immediately and skip the
130	            // retry machinery that $tries = 3 would otherwise trigger.
131	            Log::warning('ProcessImageVariantsJob: unprocessable image, failing without retry.', [
132	                'image_id' => $this->imageId,
133	                'error' => $e->getMessage(),
134	            ]);
135	
136	            $this->markFailed($e->getMessage());
137	            $this->fail($e);
138	
139	            return;
140	        } catch (Throwable $e) {
141	            Log::error('ProcessImageVariantsJob: variant generation failed.', [
142	                'image_id' => $this->imageId,
143	                'error' => $e->getMessage(),
144	                'exception' => get_class($e),
145	            ]);
146	
147	            throw $e;
148	        } finally {
149	            if (isset($localTmp) && file_exists($localTmp)) {
150	                @unlink($localTmp);
151	            }
152	        }
153	    }
154	
155	    public function failed(Throwable $e): void
156	    {
157	        $this->markFailed($e->getMessage());
158	    }
159	
160	    private function markFailed(string $reason): void
161	    {
162	        // Fetch before update so we have site_id for cache bust regardless of
163	        // update outcome (row may be soft-deleted by a concurrent delete).
164	        $siteMedia = SiteMedia::withTrashed()->where('id', $this->imageId)->first();
165	
166	        $updated = SiteMedia::query()
167	            ->where('id', $this->imageId)
168	            ->whereNull('deleted_at')
169	            ->update([
170	                'processing_state' => SiteMedia::PROCESSING_STATE_FAILED,
171	                'processing_error' => $reason,
172	            ]);
173	
174	        if ($updated === 0) {
175	            Log::info('ProcessImageVariantsJob: failed-state update skipped.', [
176	                'image_id' => $this->imageId,
177	                'row_exists' => $siteMedia !== null,
178	                'is_soft_deleted' => $siteMedia?->trashed() ?? false,
179	            ]);
180	        }
181	
182	        // Mirror the success-path cache bust (line 119-121): Hydrogen's
183	        // listDesignMedia filters on ready, so a failed design row changes
184	        // the payload shape — bust so the dashboard sees it immediately.
185	        if ($siteMedia?->pool === SiteMedia::POOL_DESIGN && $siteMedia->site_id) {
186	            try {
187	                app(SiteCacheService::class)->forgetBrandDesign((string) $siteMedia->site_id);
188	            } catch (Throwable $e) {
189	                Log::warning('ProcessImageVariantsJob: failed-state cache bust failed.', [
190	                    'image_id' => $this->imageId,
191	                    'error' => $e->getMessage(),
192	                ]);
193	            }
194	        }
195	    }
196	}
