10	/**
11	 * Generates universal WebP image variants from an uploaded original and
12	 * persists them to the configured media disk (S3-compatible / R2).
13	 *
14	 * Every image (gallery or content) gets the same configured variant set.
15	 * Current default produces two full-resolution variants:
16	 * - optimized (target-size adaptive quality)
17	 * - maximized (highest quality)
18	 *
19	 * Requires the GD extension with WebP support (ships with PHP 8.2+).
20	 */
21	// V2: Generates WebP image variants from uploads via GD. Content-hashed storage on Cloudflare R2 with adaptive quality targeting.
22	class ImageVariantService
23	{
24	    /* ------------------------------------------------------------------ */
25	    /*  Public API */
26	    /* ------------------------------------------------------------------ */
27	
28	    /**
29	     * Process an original image into all configured variants, store them
30	     * on the media disk, and persist ImageVariant rows for the given image.
31	     *
32	     * @param  string  $originalTmpPath  Absolute path to the temp original.
33	     * @param  string  $imageId  UUID of the SiteMedia row.
34	     * @param  string  $basePath  e.g. "images/<proId>/<imageId>"
35	     * @return array<string, MediaVariant> keyed by variant name
36	     */
37	    public function processVariants(
38	        string $originalTmpPath,
39	        string $imageId,
40	        string $basePath,
41	    ): array {
42	        // Ensure GD extension is available with WebP support
43	        if (! extension_loaded('gd')) {
44	            throw new \RuntimeException('GD extension is not loaded. Cannot process image variants.');
45	        }
46	
47	        if (! function_exists('imagewebp')) {
48	            throw new \RuntimeException('GD WebP support is not available. Cannot generate WebP variants.');
49	        }
50	
51	        \Illuminate\Support\Facades\Log::info('Starting image variant processing', [
52	            'image_id' => $imageId,
53	            'base_path' => $basePath,
54	        ]);
55	
56	        $disk = $this->disk();
57	        $definitions = $this->variantDefinitions();
58	
59	        $sourceImage = $this->loadImage($originalTmpPath);
60	
61	        if (! $sourceImage) {
62	            throw new \RuntimeException('Failed to create GD image from the uploaded file.');
63	        }
64	
65	        $sourceWidth = imagesx($sourceImage);
66	        $sourceHeight = imagesy($sourceImage);
67	
68	        $created = [];
69	
70	        try {
71	            foreach ($definitions as $variantName => $def) {
72	                $quality = max(1, min(100, (int) ($def['quality'] ?? 92)));
73	                $minQuality = max(1, min($quality, (int) ($def['min_quality'] ?? 60)));
74	                $targetKb = max(0, (int) ($def['target_kb'] ?? 0));
75	                $targetBytes = $targetKb > 0 ? ($targetKb * 1024) : null;
76	                $fit = (string) ($def['fit'] ?? 'inside');
77	
78	                $preserveResolution = filter_var(
79	                    $def['preserve_resolution'] ?? false,
80	                    FILTER_VALIDATE_BOOLEAN,
81	                    FILTER_NULL_ON_FAILURE,
82	                );
83	                $preserveResolution = $preserveResolution ?? false;
84	
85	                if ($preserveResolution) {
86	                    [$cropX, $cropY, $cropW, $cropH, $dstW, $dstH] = [0, 0, $sourceWidth, $sourceHeight, $sourceWidth, $sourceHeight];
87	                } else {
88	                    $targetW = max(1, (int) ($def['width'] ?? $sourceWidth));
89	                    $targetH = max(1, (int) ($def['height'] ?? $sourceHeight));
90	
91	                    // Backward-compatible path for capped variants.
92	                    [$cropX, $cropY, $cropW, $cropH, $dstW, $dstH] = $this->calculateDimensions(
93	                        $sourceWidth, $sourceHeight, $targetW, $targetH, $fit,
94	                    );
95	                }
96	
97	                $canvas = imagecreatetruecolor($dstW, $dstH);
98	                imagealphablending($canvas, false);
99	                imagesavealpha($canvas, true);
100	
101	                imagecopyresampled(
102	                    $canvas, $sourceImage,
103	                    0, 0, $cropX, $cropY,
104	                    $dstW, $dstH, $cropW, $cropH,
105	                );
106	
107	                // --- Encode to WebP ---
108	                $tmpFile = tempnam(sys_get_temp_dir(), 'sidest_img_');
109	                if (! is_string($tmpFile) || $tmpFile === '') {
110	                    throw new \RuntimeException('Failed to create temp file for WebP encoding.');
111	                }
112	
113	                try {
114	                    $encodedQuality = $quality;
115	                    if ($targetBytes !== null) {
116	                        $encodedQuality = $this->encodeWebpToTargetSize(
117	                            image: $canvas,
118	                            tmpFile: $tmpFile,
119	                            maxQuality: $quality,
120	                            minQuality: $minQuality,
121	                            targetBytes: $targetBytes,
122	                        );
123	                    } else {
124	                        $this->encodeWebp($canvas, $tmpFile, $quality);
125	                    }
126	
127	                    $fileBytes = filesize($tmpFile);
128	                    if ($fileBytes === false) {
129	                        throw new \RuntimeException('Failed to determine encoded WebP file size.');
130	                    }
131	
132	                    if ($targetBytes !== null && $fileBytes > $targetBytes) {
133	                        Log::warning('Image variant exceeded target size at min quality.', [
134	                            'image_id' => $imageId,
135	                            'variant' => $variantName,
136	                            'target_kb' => $targetKb,
137	                            'actual_kb' => (int) round($fileBytes / 1024),
138	                            'quality_used' => $encodedQuality,
139	                        ]);
140	                    }
141	
142	                    $hash = hash_file('sha256', $tmpFile);
143	                    if (! is_string($hash)) {
144	                        throw new \RuntimeException('Failed to hash encoded WebP variant.');
145	                    }
146	                    $hash = substr($hash, 0, 16);
147	
148	                    // Content-hashed filename: optimized_abc123def456.webp
149	                    $storagePath = "{$basePath}/{$variantName}_{$hash}.webp";
150	
151	                    // --- Upload to bucket ---
152	                    $payload = file_get_contents($tmpFile);
153	                    if ($payload === false) {
154	                        throw new \RuntimeException('Failed to read encoded WebP for upload.');
155	                    }
156	                    $disk->put($storagePath, $payload, 'public');
157	
158	                    // --- Upsert DB row ---
159	                    $variant = MediaVariant::updateOrCreate(
160	                        [
161	                            'media_id' => $imageId,
162	                            'variant_key' => $variantName,
163	                            'artifact_type' => 'webp',
164	                        ],
165	                        [
166	                            'disk' => $this->diskName(),
167	                            'path' => $storagePath,
168	                            'mime' => 'image/webp',
169	                            'width' => $dstW,
170	                            'height' => $dstH,
171	                            'file_size_bytes' => $fileBytes,
172	                            'content_hash' => $hash,
173	                        ],
174	                    );
175	
176	                    $created[$variantName] = $variant;
177	                } finally {
178	                    @unlink($tmpFile);
179	                    unset($canvas);
180	                }
181	            }
182	        } finally {
183	            unset($sourceImage);
184	        }
185	
186	        \Illuminate\Support\Facades\Log::info('Image variant processing completed', [
187	            'image_id' => $imageId,
188	            'variant_count' => count($created),
189	        ]);
190	
191	        return $created;
192	    }
193	
194	    /**
195	     * Store the original upload to a location on the media disk
196	     * (kept for disaster-recovery / re-processing).
197	     *
198	     * Returns the storage path of the original.
199	     */
200	    public function storeOriginal(UploadedFile $file, string $basePath): string
201	    {
202	        $ext = $file->getClientOriginalExtension() ?: 'jpg';
203	        $hash = substr(hash_file('sha256', $file->getRealPath()), 0, 16);
204	        $path = "{$basePath}/original_{$hash}.{$ext}";
205	
206	        $this->disk()->put($path, file_get_contents($file->getRealPath()), 'public');
207	
208	        return $path;
209	    }
