211	    /**
212	     * Delete all image variant files (and DB rows) for a given SiteMedia item,
213	     * plus the original file stored at the image's path.
214	     */
215	    public function deleteVariants(string $imageId, ?string $originalPath = null): void
216	    {
217	        $variants = MediaVariant::where('media_id', $imageId)
218	            ->where('artifact_type', 'webp')
219	            ->get();
220	        $disk = $this->disk();
221	
222	        foreach ($variants as $variant) {
223	            $disk->delete($variant->path);
224	            $variant->delete();
225	        }
226	
227	        // Also remove the original if a path was provided
