233	    /**
234	     * Build a variant map (variant_key → public URL) for a SiteMedia image item.
235	     *
236	     * @return array<string, string>
237	     */
238	    public function variantUrls(string $imageId): array
239	    {
240	        return MediaVariant::where('media_id', $imageId)
241	            ->where('artifact_type', 'webp')
242	            ->get()
