247	    /**
248	     * Resolve the effective media disk name used for all reads/writes.
249	     */
250	    public function resolvedDiskName(): string
251	    {
252	        return $this->diskName();
253	    }
254	
255	    /* ------------------------------------------------------------------ */
256	    /*  Internal helpers */
257	    /* ------------------------------------------------------------------ */
258	
259	    private function diskName(): string
260	    {
261	        $configured = (string) config('sidest.media_disk', 'media');
262	
263	        // $_ENV/$_SERVER are intentional here — Laravel Cloud caches config at deploy time
264	        // but injects platform env vars directly into the process environment at runtime,
265	        // so env()/config() won't see them. Direct superglobal access bypasses that cache.
266	        $explicit = $_ENV['SIDEST_MEDIA_DISK'] ?? $_SERVER['SIDEST_MEDIA_DISK'] ?? null;
267	        if (is_string($explicit) && trim($explicit) !== '') {
268	            return $configured;
269	        }
270	
271	        // Laravel Cloud injects disks dynamically and may set a non-"media"
272	        // filesystems.default disk. If media disk is only a fallback value,
273	        // prefer the Cloud default to avoid missing/empty media credentials.
274	        if ($configured === 'media') {
275	            $default = (string) config('filesystems.default', 'local');
276	            $defaultConfig = config("filesystems.disks.{$default}");
277	
278	            if (
279	                $default !== '' &&
280	                $default !== 'local' &&
281	                $default !== 'media' &&
282	                is_array($defaultConfig) &&
283	                (($defaultConfig['driver'] ?? null) === 's3')
284	            ) {
285	                Log::warning('SIDEST_MEDIA_DISK not set; using filesystems.default disk for media operations.', [
286	                    'configured_media_disk' => $configured,
287	                    'fallback_disk' => $default,
288	                ]);
289	
290	                return $default;
291	            }
292	        }
293	
294	        return $configured;
295	    }
