302	    /**
303	     * Universal variant definitions (same for all images).
304	     */
305	    private function variantDefinitions(): array
306	    {
307	        $definitions = (array) config('sidest.image_variants', []);
308	
309	        if ($definitions !== []) {
310	            return $definitions;
311	        }
312	
313	        // NOTE: this fallback MUST mirror config/sidest.php image_variants exactly.
314	        // It runs only when config is empty (sparse test environments).
315	        return [
316	            'optimized' => [
317	                'format' => 'webp',
318	                'width' => 2400,
319	                'height' => 2400,
320	                'fit' => 'inside',
321	                'quality' => 92,
322	                'min_quality' => 60,
323	                'target_kb' => 500,
324	            ],
325	            'maximized' => [
326	                'format' => 'webp',
327	                'width' => 4000,
328	                'height' => 4000,
329	                'fit' => 'inside',
330	                'quality' => 92,
331	            ],
332	        ];
333	    }
