335	    /**
336	     * Load an image file into a GD resource regardless of source format.
337	     *
338	     * Refuses images whose pixel count exceeds sidest.image_max_pixels by
339	     * throwing UnprocessableImageException BEFORE any bitmap memory is
340	     * allocated. This is the defense against image-bomb uploads — a tiny
341	     * JPEG/PNG file can decode to a huge bitmap (4 bytes per pixel), which
342	     * the worker cannot survive even with the canvas caps applied.
343	     *
344	     * The getimagesize() call reads only the file header (a few KB), not
345	     * the pixel data, so the guard is effectively free.
346	     */
347	    private function loadImage(string $path): \GdImage|false
348	    {
349	        $info = @getimagesize($path);
350	        if (! $info) {
351	            return false;
352	        }
353	
354	        $width = (int) $info[0];
355	        $height = (int) $info[1];
356	        $maxPixels = (int) config('sidest.image_max_pixels', 24_000_000);
357	
358	        if ($width * $height > $maxPixels) {
359	            throw new UnprocessableImageException(sprintf(
360	                'Image dimensions exceed safe processing limit (%d x %d = %d pixels, max %d).',
361	                $width,
362	                $height,
363	                $width * $height,
364	                $maxPixels,
365	            ));
366	        }
367	
368	        return match ($info[2]) {
369	            IMAGETYPE_JPEG => @imagecreatefromjpeg($path),
370	            IMAGETYPE_PNG => @imagecreatefrompng($path),
371	            IMAGETYPE_WEBP => @imagecreatefromwebp($path),
372	            default => false,
373	        };
374	    }
375	
376	    /**
377	     * Encode an image as WebP at the given quality and return file size.
378	     */
379	    private function encodeWebp(\GdImage $image, string $tmpFile, int $quality): int
380	    {
381	        if (@imagewebp($image, $tmpFile, $quality) === false) {
382	            throw new \RuntimeException("Failed to encode WebP at quality {$quality}.");
383	        }
384	
385	        clearstatcache(true, $tmpFile);
386	        $size = filesize($tmpFile);
387	        if ($size === false) {
388	            throw new \RuntimeException('Failed to read encoded WebP size.');
389	        }
390	
391	        return $size;
392	    }
393	
394	    /**
395	     * Binary-search the highest quality that stays under target bytes.
396	     *
397	     * Returns the quality used for the final file in $tmpFile.
398	     */
399	    private function encodeWebpToTargetSize(
400	        \GdImage $image,
401	        string $tmpFile,
402	        int $maxQuality,
403	        int $minQuality,
404	        int $targetBytes,
405	    ): int {
406	        $lower = max(1, min(100, $minQuality));
407	        $upper = max($lower, min(100, $maxQuality));
408	
409	        $bestQuality = null;
410	
411	        while ($lower <= $upper) {
412	            $mid = intdiv($lower + $upper, 2);
413	            $size = $this->encodeWebp($image, $tmpFile, $mid);
414	
415	            if ($size <= $targetBytes) {
416	                $bestQuality = $mid;
417	                $lower = $mid + 1;
418	
419	                continue;
420	            }
421	
422	            $upper = $mid - 1;
423	        }
424	
425	        if ($bestQuality !== null) {
426	            $this->encodeWebp($image, $tmpFile, $bestQuality);
427	
428	            return $bestQuality;
429	        }
430	
431	        // Could not satisfy target even at min quality.
432	        $this->encodeWebp($image, $tmpFile, max(1, min(100, $minQuality)));
433	
434	        return max(1, min(100, $minQuality));
435	    }
436	
437	    /**
438	     * Calculate crop / resize geometry.
439	     *
440	     * @return array [cropX, cropY, cropW, cropH, dstW, dstH]
441	     */
442	    private function calculateDimensions(
443	        int $srcW, int $srcH,
444	        int $maxW, int $maxH,
445	        string $fit,
446	    ): array {
447	        if ($fit === 'cover') {
448	            $srcRatio = $srcW / $srcH;
449	            $dstRatio = $maxW / $maxH;
450	
451	            if ($srcRatio > $dstRatio) {
452	                $cropH = $srcH;
453	                $cropW = (int) round($srcH * $dstRatio);
454	                $cropX = (int) round(($srcW - $cropW) / 2);
455	                $cropY = 0;
456	            } else {
457	                $cropW = $srcW;
458	                $cropH = (int) round($srcW / $dstRatio);
459	                $cropX = 0;
460	                $cropY = (int) round(($srcH - $cropH) / 2);
461	            }
462	
463	            return [$cropX, $cropY, $cropW, $cropH, $maxW, $maxH];
464	        }
465	
466	        // "inside" – fit within bounds, no crop, never upscale
467	        $ratio = min($maxW / $srcW, $maxH / $srcH, 1);
468	        $dstW = (int) round($srcW * $ratio);
469	        $dstH = (int) round($srcH * $ratio);
470	
471	        return [0, 0, $srcW, $srcH, $dstW, $dstH];
472	    }
473	}
