3	namespace App\Services\Media;
4	
5	use App\Models\Core\MediaVariant;
6	use App\Models\Core\Site\SiteMedia;
7	use Illuminate\Support\Facades\Log;
8	use Illuminate\Support\Facades\Storage;
9	use Symfony\Component\Process\Process;
10	
11	/**
12	 * Transcodes a video original into MP4 + HLS variants and a poster image,
13	 * stores all artifacts on the media disk, and persists MediaVariant rows.
14	 *
15	 * Processing order (avoids extra re-encodes):
16	 *   1. FFprobe  – extract metadata + validate duration
17	 *   2. FFmpeg   – encode optimized MP4 (720p)
18	 *   3. FFmpeg   – encode maximized MP4 (1080p)
19	 *   4. FFmpeg   – package HLS segments from each MP4 (stream-copy, no re-encode)
20	 *   5. Build    – write master adaptive HLS playlist
21	 *   6. FFmpeg   – extract poster JPEG at 1s mark
22	 *   7. Upload   – stream all artifacts to media disk
23	 *   8. DB upsert – persist one MediaVariant row per logical artifact
24	 *   9. SiteMedia update – set processing_state, duration_ms, poster_path
25	 *
26	 * Storage layout under the media disk:
27	 *   videos/{proId}/{mediaId}/
28	 *     original_{hash}.{ext}
29	 *     optimized.mp4
30	 *     maximized.mp4
31	 *     hls/
32	 *       optimized/playlist.m3u8  + seg_*.ts
33	 *       maximized/playlist.m3u8  + seg_*.ts
34	 *       adaptive.m3u8             (master playlist)
35	 *     poster.jpg
36	 *
37	 * Requires ffmpeg and ffprobe to be available (configured via config/sidest.php).
38	 */
39	// V2: Transcodes videos to MP4 + HLS via FFmpeg. Feature-flagged (SIDEST_VIDEO_UPLOADS_ENABLED). Uses dedicated redis_video connection.
40	class VideoVariantService
41	{
42	    /* ------------------------------------------------------------------ */
43	    /*  Public API */
44	    /* ------------------------------------------------------------------ */
45	
46	    /**
47	     * Run FFprobe on a local file and return metadata array.
48	     * Throws \RuntimeException if the binary fails.
49	     *
50	     * @return array<string, mixed>
51	     */
52	    public function probe(string $localPath): array
53	    {
54	        $ffprobe = $this->ffprobeBinary();
55	        $cmd = sprintf(
56	            '%s -v quiet -print_format json -show_format -show_streams %s 2>&1',
57	            escapeshellcmd($ffprobe),
58	            escapeshellarg($localPath),
59	        );
60	
61	        $output = $this->runCommand($cmd, $exitCode);
62	
63	        if ($exitCode !== 0) {
64	            throw new \RuntimeException("ffprobe failed (exit {$exitCode}): {$output}");
65	        }
66	
67	        $data = json_decode($output, true);
68	        if (! is_array($data)) {
69	            throw new \RuntimeException('ffprobe returned non-JSON output.');
70	        }
71	
72	        return $data;
73	    }
74	
75	    /**
76	     * Process a video original into all configured artifacts.
77	     *
78	     * @throws \RuntimeException on unrecoverable processing errors
79	     */
80	    public function processVariants(
81	        string $localOriginalPath,
82	        string $mediaId,
83	        string $basePath,
84	    ): void {
85	        Log::info('VideoVariantService: starting', [
86	            'media_id' => $mediaId,
87	            'base_path' => $basePath,
88	        ]);
89	
90	        // --- 1. Probe metadata ---
91	        $probe = $this->probe($localOriginalPath);
92	        $durationMs = $this->extractDurationMs($probe);
93	        $maxDur = (int) config('sidest.video_max_duration_seconds', 300);
94	
95	        if ($durationMs > $maxDur * 1000) {
96	            throw new \RuntimeException(
97	                "Video duration ({$durationMs}ms) exceeds maximum ({$maxDur}s)."
98	            );
99	        }
100	
101	        $variantDefs = (array) config('sidest.video_variants', []);
102	        $tmpDirs = [];
103	
104	        try {
105	            // --- 2 & 3. Encode MP4 variants ---
106	            $mp4Paths = [];
107	            foreach ($variantDefs as $variantKey => $def) {
108	                $tmpMp4 = $this->makeTmpFile("sidest_mp4_{$variantKey}_", '.mp4');
109	                $this->encodeMp4($localOriginalPath, $tmpMp4, $def);
110	                $mp4Paths[$variantKey] = $tmpMp4;
111	            }
112	
113	            // --- 4. Package HLS from each MP4 ---
114	            $hlsDirs = [];
115	            foreach ($mp4Paths as $variantKey => $mp4) {
116	                $tmpHlsDir = sys_get_temp_dir().'/sidest_hls_'.$variantKey.'_'.uniqid();
117	                if (! mkdir($tmpHlsDir, 0755, true)) {
118	                    throw new \RuntimeException("Failed to create HLS temp dir: {$tmpHlsDir}");
119	                }
120	                $tmpDirs[] = $tmpHlsDir;
121	                $this->packageHls($mp4, $tmpHlsDir.'/playlist.m3u8');
122	                $hlsDirs[$variantKey] = $tmpHlsDir;
123	            }
124	
125	            // --- 5. Build adaptive master playlist ---
126	            $adaptiveContent = $this->buildAdaptivePlaylist($variantDefs);
127	
128	            // --- 6. Extract poster ---
129	            $tmpPoster = $this->makeTmpFile('sidest_poster_', '.jpg');
130	            $this->extractPoster($localOriginalPath, $tmpPoster);
131	
132	            // --- 7. Upload all artifacts ---
133	            $disk = $this->disk();
134	            $diskName = $this->resolvedDiskName();
135	
136	            // Upload MP4s
137	            foreach ($mp4Paths as $variantKey => $mp4) {
138	                $remotePath = "{$basePath}/{$variantKey}.mp4";
139	                $stream = fopen($mp4, 'rb');
140	                $disk->put($remotePath, $stream, 'public');
141	                if (is_resource($stream)) {
142	                    fclose($stream);
143	                }
144	
145	                $def = $variantDefs[$variantKey] ?? [];
146	                // Unique key: (media_id, variant_key, artifact_type)
147	                MediaVariant::updateOrCreate(
148	                    ['media_id' => $mediaId, 'variant_key' => $variantKey, 'artifact_type' => 'mp4'],
149	                    [
150	                        'disk' => $diskName,
151	                        'path' => $remotePath,
152	                        'mime' => 'video/mp4',
