398	    /**
399	     * Build the adaptive (master) HLS playlist content.
400	     *
401	     * @param  array<string, array<string, mixed>>  $variantDefs
402	     */
403	    private function buildAdaptivePlaylist(array $variantDefs): string
404	    {
405	        $lines = ['#EXTM3U'];
406	
407	        foreach ($variantDefs as $variantKey => $def) {
408	            $videoBitrate = (int) ($def['video_bitrate_kbps'] ?? 2000);
409	            $audioBitrate = (int) ($def['audio_bitrate_kbps'] ?? 128);
410	            $bandwidth = ($videoBitrate + $audioBitrate) * 1000;
411	            $resolution = strtoupper((string) ($def['resolution'] ?? '1280x720'));
412	
413	            $lines[] = "#EXT-X-STREAM-INF:BANDWIDTH={$bandwidth},RESOLUTION={$resolution}";
414	            $lines[] = "{$variantKey}/playlist.m3u8";
415	        }
416	
417	        return implode("\n", $lines)."\n";
418	    }
