420	    private function extractDurationMs(array $probe): int
421	    {
422	        $duration = $probe['format']['duration'] ?? null;
423	        if ($duration === null) {
424	            // Fall back to the first video stream
425	            foreach ($probe['streams'] ?? [] as $stream) {
426	                if (($stream['codec_type'] ?? '') === 'video' && isset($stream['duration'])) {
427	                    $duration = $stream['duration'];
428	                    break;
429	                }
430	            }
431	        }
432	
433	        return $duration !== null ? (int) round((float) $duration * 1000) : 0;
434	    }
