436	    private function makeTmpFile(string $prefix, string $suffix): string
437	    {
438	        $path = tempnam(sys_get_temp_dir(), $prefix);
439	        if (! $path) {
440	            throw new \RuntimeException("Failed to create temp file ({$prefix}).");
441	        }
442	
443	        // Rename to add the desired extension so FFmpeg knows the container.
444	        $withExt = $path.$suffix;
445	        rename($path, $withExt);
446	
447	        return $withExt;
448	    }
