450	    /**
451	     * Run a pre-escaped shell command via Symfony Process and return its output.
452	     * $exitCode is set by reference.
453	     *
454	     * All arguments in $cmd must be escaped by the caller via
455	     * escapeshellcmd()/escapeshellarg() before this method is called.
456	     * No timeout is applied — video encoding can be arbitrarily long.
457	     */
458	    private function runCommand(string $cmd, ?int &$exitCode = null): string
459	    {
460	        $process = Process::fromShellCommandline($cmd);
461	        $process->setTimeout(null);
462	        $process->run();
463	
464	        $exitCode = $process->getExitCode() ?? 0;
465	
466	        // Callers append 2>&1, so all output (including stderr) is in stdout
467	        return $process->getOutput();
468	    }
