470	    private function removeDir(string $dir): void
471	    {
472	        if (! is_dir($dir)) {
473	            return;
474	        }
475	
476	        foreach (scandir($dir) ?: [] as $file) {
477	            if ($file === '.' || $file === '..') {
478	                continue;
479	            }
480	            $path = "{$dir}/{$file}";
481	            is_dir($path) ? $this->removeDir($path) : @unlink($path);
482	        }
483	
484	        @rmdir($dir);
485	    }
