487	    /**
488	     * Legacy jobs may pass the original file path instead of the media directory.
489	     * Normalize to the directory prefix expected by allFiles().
490	     */
491	    private function normalizeVideoCleanupBasePath(string $basePath): string
492	    {
493	        $normalized = trim($basePath);
494	        if ($normalized === '') {
495	            throw new \RuntimeException('Video cleanup base path cannot be empty.');
496	        }
497	
498	        $leaf = basename($normalized);
499	        if (str_contains($leaf, '.')) {
500	            $normalized = dirname($normalized);
501	        }
502	
503	        $normalized = trim($normalized, '/');
504	        if ($normalized === '' || $normalized === '.') {
505	            throw new \RuntimeException('Video cleanup base path resolved to an invalid directory.');
506	        }
507	
508	        return $normalized;
509	    }
510	
511	    private function diskName(): string
512	    {
513	        $configured = (string) config('sidest.media_disk', 'media');
514	
515	        // $_ENV/$_SERVER are intentional here — Laravel Cloud caches config at deploy time
516	        // but injects platform env vars directly into the process environment at runtime,
517	        // so env()/config() won't see them. Direct superglobal access bypasses that cache.
518	        $explicit = $_ENV['SIDEST_MEDIA_DISK'] ?? $_SERVER['SIDEST_MEDIA_DISK'] ?? null;
519	        if (is_string($explicit) && trim($explicit) !== '') {
520	            return $configured;
521	        }
522	
523	        if ($configured === 'media') {
524	            $default = (string) config('filesystems.default', 'local');
525	            $defaultConfig = config("filesystems.disks.{$default}");
526	
527	            if (
528	                $default !== '' &&
529	                $default !== 'local' &&
530	                $default !== 'media' &&
531	                is_array($defaultConfig) &&
532	                (($defaultConfig['driver'] ?? null) === 's3')
533	            ) {
534	                return $default;
535	            }
536	        }
537	
538	        return $configured;
539	    }
